// ═══ THE PROBLEM — blocking IO on commonPool ═══
// commonPool parallelism: 3 threads (on 4-core machine)

// Component A: 3 slow JDBC queries via supplyAsync (default pool!)
for (int i = 0; i < 3; i++) {
    CompletableFuture.supplyAsync(() -> {
        return jdbcTemplate.queryForObject("SELECT ...", String.class);
        // Blocks 2 seconds! All 3 commonPool threads occupied!
    });
}

// Component B (UNRELATED): parallel stream for report generation
report = accounts.parallelStream()  // ALSO uses commonPool!
    .map(this::generateStatement)    // STALLED! All 3 workers blocked by Component A!
    .collect(Collectors.toList());
// Report generation WAITS 2 seconds because JDBC monopolized the pool!

// Component C (UNRELATED): CompletableFuture for notifications
CompletableFuture.supplyAsync(() -> sendNotification());  // QUEUED behind JDBC!
// Notification delayed by unrelated database queries!

// ═══ WHO SHARES commonPool? ═══
// 1. CompletableFuture.supplyAsync() (no executor param)
// 2. parallelStream()
// 3. Arrays.parallelSort()
// 4. Many frameworks (Spring WebFlux internals, etc.)
// ALL compete for the same 3 threads!

// ═══ FIX: dedicated pools ═══
ExecutorService jdbcPool = Executors.newFixedThreadPool(20);  // IO: many threads
ExecutorService notifyPool = Executors.newFixedThreadPool(10);

CompletableFuture.supplyAsync(() -> jdbcQuery(), jdbcPool);     // on jdbcPool!
CompletableFuture.supplyAsync(() -> sendNotif(), notifyPool);    // on notifyPool!
accounts.parallelStream().map(...);  // commonPool free for this!

