// ─── File: src/test/java/com/bank/isolation/ResourceIsolationTest.java ───
package com.bank.isolation;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class ResourceIsolationTest {

    void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) {} }

    // ═══ PROBLEM: blocking IO starves commonPool ═══
    @Test
    void blockingIO_starvesCommonPool() throws Exception {
        int parallelism = ForkJoinPool.commonPool().getParallelism();
        System.out.println("commonPool parallelism: " + parallelism);

        // Fill commonPool with blocking IO:
        for (int i = 0; i < parallelism; i++) {
            CompletableFuture.runAsync(() -> sleep(2000));  // blocks 2s!
        }
        Thread.sleep(100);  // let them start

        // Now try a quick task on commonPool:
        long start = System.currentTimeMillis();
        CompletableFuture.runAsync(() -> {}).get(5, TimeUnit.SECONDS);
        long elapsed = System.currentTimeMillis() - start;

        System.out.println("Quick task waited: " + elapsed + "ms (should be ~0ms!)");
        // Likely waited ~2000ms for a blocking thread to finish!
    }

    // ═══ PROBLEM: parallelStream also affected ═══
    @Test
    void parallelStream_starvedByBlockingCF() throws Exception {
        int parallelism = ForkJoinPool.commonPool().getParallelism();

        // Block all commonPool threads:
        for (int i = 0; i < parallelism; i++) {
            CompletableFuture.runAsync(() -> sleep(1000));
        }
        Thread.sleep(100);

        // parallelStream uses SAME pool → starved!
        long start = System.currentTimeMillis();
        IntStream.range(0, 10).parallel().forEach(i -> sleep(10));
        long elapsed = System.currentTimeMillis() - start;

        System.out.println("parallelStream waited: " + elapsed + "ms");
        // Much slower than expected!
    }

    // ═══ FIX: dedicated pools → no starvation ═══
    @Test
    void dedicatedPools_noStarvation() throws Exception {
        ExecutorService ioPool = Executors.newFixedThreadPool(10);

        // IO on dedicated pool:
        for (int i = 0; i < 10; i++) {
            CompletableFuture.runAsync(() -> sleep(500), ioPool);  // ioPool!
        }

        // Quick task on commonPool — NOT starved!
        long start = System.currentTimeMillis();
        CompletableFuture.runAsync(() -> {}).get(5, TimeUnit.SECONDS);
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isLessThan(100);  // instant! commonPool free!

        // parallelStream — also NOT starved!
        long start2 = System.currentTimeMillis();
        long sum = IntStream.range(0, 100).parallel().mapToLong(i -> i * i).sum();
        long elapsed2 = System.currentTimeMillis() - start2;

        assertThat(elapsed2).isLessThan(100);  // fast! commonPool available!
        ioPool.shutdown();
    }
}
